INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q1 Item 1 (TPS 2014): A respeito do excerto acima, extraído do poema Improviso do mal da América, de Mário de Andrade, julgue (C ou E) os itens subsequentes. | Na descrição de alguns hábitos dos estrangeiros que chegam a São Paulo, predomina a perspectiva da cultura brasileira, como se verifica principalmente nos versos “Detestam caninha, detestam mandioca e pimenta,/Não dançam maxixe, nem dançam catira, nem sabem amar suspirado” (v.15 e v.16).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q1 Item 2 (TPS 2014): A respeito do excerto acima, extraído do poema Improviso do mal da América, de Mário de Andrade, julgue (C ou E) os itens subsequentes. | No primeiro verso do excerto, o eu lírico associa a percepção de se sentir branco ao pertencimento de realidades desconhecidas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q1 Item 3 (TPS 2014): A respeito do excerto acima, extraído do poema Improviso do mal da América, de Mário de Andrade, julgue (C ou E) os itens subsequentes. | Os versos de 1 a 9 expressam a inanição do eu lírico resultante do desejo de “tudo ir indo de rodada mansamente” (v.3).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q1 Item 4 (TPS 2014): A respeito do excerto acima, extraído do poema Improviso do mal da América, de Mário de Andrade, julgue (C ou E) os itens subsequentes. | A hostilidade do eu lírico com os inúmeros migrantes que chegam a São Paulo tem como contraponto a acolhida a todos eles no “quarto de hóspedes acolhedor da Sulamérica” (v.12).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q2 Item 1 (TPS 2014): Com base no excerto do poema Improviso do mal da América, de Mário de Andrade, julgue (C ou E) os próximos itens. | No verso “As mulheres fumam feito chaminés sozinhas” (v.18), a posição do adjetivo resulta em ambiguidade estrutural.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q2 Item 2 (TPS 2014): Com base no excerto do poema Improviso do mal da América, de Mário de Andrade, julgue (C ou E) os próximos itens. | No trecho “E como sempre entre eles tem sempre um que manda sempre em todos,/Tudo calou de supetão, e no ar amulegado da noite que sua...” (v.20 e v.21), o conector “como” introduz uma oração subordinada que expressa a causa de tudo se calar “de supetão”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q2 Item 3 (TPS 2014): Com base no excerto do poema Improviso do mal da América, de Mário de Andrade, julgue (C ou E) os próximos itens. | No verso “E faça tudo ir indo de rodada mansamente” (v.3), o poeta utilizou a redundância como recurso expressivo, como evidencia o caráter expletivo da forma de infinitivo “ir”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q2 Item 4 (TPS 2014): Com base no excerto do poema Improviso do mal da América, de Mário de Andrade, julgue (C ou E) os próximos itens. | Os vocábulos “amorosos” (v.5) e “suspirado” (v.16) mantêm o mesmo tipo de relação sintática com os verbos que os precedem. ADMISSÃO À CARREIRA DE DIPLOMATA – MANHÃ – 1 – ||IRBR14DIPL_001_01N157490|| CESPE/UnB – IRBr DIPLOMATA – Aplicação: 2014', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q3 Item 1 (TPS 2014):  | Que me perdoem os devotos machadianos, eu prefiro Euclides da Cunha e Lima Barreto, com todos os defeitos que ambos possam ter, a Machado de Assis, com todas as suas', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q3 Item 2 (TPS 2014):  | qualidades. E, até onde pude entender, Millôr Fernandes tem opinião parecida com a minha. Tanto assim que, segundo afirmou, não incluiria qualquer dos livros de Machado de Assis 7 entre os dez maiores romances brasileiros. A meu ver, ao falar assim, Millôr Fernandes levou em conta apenas livros como Dom Casmurro, em que, na minha 10 opinião, Machado incorre naquela miopia contra a qual o músico Jayme Ovalle reclamava. Mas esqueceu de Quincas Borba, que inclui Machado de Assis na linhagem cervantina da 13 literatura e em que a insânia de Rubião se aproxima da insânia do Cavaleiro da Triste Figura. Mas, talvez por causa da ironia sem compaixão de 16 Machado de Assis, a loucura de Rubião gira somente em torno de sua pessoa, jamais partindo ele para qualquer ação no sentido de corrigir “os des', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q4 Item 1 (TPS 2014):  | A correspondência de Mário de Andrade é uma das fontes sobre os sentimentos que abateram a intelectualidade paulista, sobretudo no trauma de 1932, quando São Paulo foi', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q4 Item 2 (TPS 2014):  | invadido por tropas federais, que ocuparam a capital e se alastraram pelo interior (“Disputam esfomeadamente a presa sublime, e desgraçadamente está certo, essa é a lei dos homens. 7 Dos homens selvagens.”, desabafa Mário em carta a Paulo Duarte). As consequências dos expedientes da ditadura abateram um estado cujos habitantes eram considerados por 10 Mário como “diferentes mesmo”. O que se fizesse naquele estado, apostava, se irradiaria como política e como orientação pelo país, uma reedição, por via da cultura, do velho slogan: 13 “São Paulo, a locomotiva puxando os vagões”. “Minha pátria é São Paulo. E isso não me desagrada.”, confessa o poeta paulista a Drummond no calor de um conflito 16 que os encontrou em lados opostos. Drummond já estava na chefia de gabinete do secretário de Inter', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q4 Item 3 (TPS 2014):  | A crônica não é um “gênero maior”. Não se imagina uma literatura feita de grandes cronistas, que lhe dessem o brilho universal dos grandes romancistas, dramaturgos e', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q4 Item 4 (TPS 2014):  | poetas. Nem se pensaria em atribuir o Prêmio Nobel a um cronista, por melhor que fosse. Portanto, parece mesmo que a crônica é um gênero menor. 7 “Graças a Deus”, seria o caso de dizer, porque, sendo assim, ela fica mais perto de nós. E para muitos pode servir de caminho não apenas para a vida, que ela serve de perto, mas 10 para a literatura. Por meio dos assuntos, da composição solta, do ar de coisa sem necessidade que costuma assumir, ela se ajusta à sensibilidade de todo dia. Principalmente porque 13 elabora uma linguagem que fala de perto ao nosso modo de ser mais natural. Na sua despretensão, humaniza; e esta humanização lhe permite, como compensação sorrateira, 16 recuperar com a outra mão certa profundidade de significado e certo acabamento de forma, que de repente podem fazer dela', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q5 Item 1 (TPS 2014): Em relação ao texto acima, julgue (C ou E) os itens a seguir. | Ao afirmar que a crônica “humaniza” (R.14) e é “uma inesperada, embora discreta, candidata à perfeição” (R.18), o autor demonstra que, de fato, o Prêmio Nobel não poderia ser atribuído a um cronista na categoria de gênero maior, mas, sim, em outra categoria.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q5 Item 2 (TPS 2014): Em relação ao texto acima, julgue (C ou E) os itens a seguir. | Ao afirmar que a crônica “fala de perto ao nosso modo de ser mais natural” (R.13-14), o autor indica que as obras de romancistas, dramaturgos e poetas demonstram maior “profundidade de significado” (R.16) e “acabamento de forma” (R.17).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q5 Item 3 (TPS 2014): Em relação ao texto acima, julgue (C ou E) os itens a seguir. | No texto, o autor indica que a crônica, apesar de ser um gênero menor, pode proporcionar acesso à literatura considerada de gênero maior, como a representada por romances, peças teatrais e poemas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q5 Item 4 (TPS 2014): Em relação ao texto acima, julgue (C ou E) os itens a seguir. | De acordo com os sentidos produzidos no texto, a expressão “compensação sorrateira” (R.15) deve ser interpretada como compensação desonesta, compensação viciada ou compensação desigual.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q6 Item 1 (TPS 2014): Ainda em relação ao texto, julgue (C ou E) os itens subsequentes. | As formas verbais “imagina” (R.1), “atribuir” (R.4) e “servir” (R.8) foram utilizadas como verbos transitivos indiretos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q6 Item 2 (TPS 2014): Ainda em relação ao texto, julgue (C ou E) os itens subsequentes. | No trecho “Principalmente porque elabora uma linguagem que fala de perto ao nosso modo de ser mais natural” (R.12-14), o autor indica que a crônica e a linguagem falada é a que consegue a mais perfeita comunicação literária.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q6 Item 3 (TPS 2014): Ainda em relação ao texto, julgue (C ou E) os itens subsequentes. | No trecho “certa profundidade de significado e certo acabamento de forma” (R.16-17), o adjetivo “certo” e sua forma flexionada no feminino foram utilizados com o sentido exato, preciso, correto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q6 Item 4 (TPS 2014): Ainda em relação ao texto, julgue (C ou E) os itens subsequentes. | Há elementos no texto que permitem deduzir que, segundo o autor, a crônica será um gênero maior quando o Prêmio Nobel for concedido a um cronista.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q7 Item 1 (TPS 2014):  | Entre os anos 70 e começos da década seguinte, vigorou o que se chamava amável e ironicamente a poesia do desbunde. Dela pode-se dizer que reaclimatou, em tom menor,', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q7 Item 2 (TPS 2014):  | o ideário modernista. Então revalorizados, o coloquial e o poema-piada deixavam de simplesmente se opor à linguagem empertigada contra a qual os modernistas haviam lutado. 7 Punham-se agora a serviço da territorialidade privada. Enquanto, no primeiro modernismo, aqueles eram meios para a redescoberta procurada do país, agora se tornavam 10 instrumentos domésticos. O país estava ocupado. O regime militar, em seu apogeu, assegurava o milagre das bolsas e o sigilo das torturas. Tratava-se para os jovens literati de salvar 13 a casa; se não toda, o quarto de fundos. Claro que não pensavam assim. Quando faziam declarações, apresentavam como seus inimigos os poetas experimentais e a poesia de João 16 Cabral. Os concretos e Cabral seriam, para eles, os homólogos contemporâneos de Coelho Neto e Ol', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q8 Item 1 (TPS 2014):  | José Lins do Rego, em ensaio admirável dedicado a Fialho de Almeida, põe talvez exagerada ênfase na condição de “telúrico” de Fialho, como virtude acima de qualquer outra', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q8 Item 2 (TPS 2014):  | num escritor. Tanto que nos dá a impressão de que, em literatura, só os telúricos se salvam. O que me parece generalização muito próxima da verdade; mas não a verdade absoluta. 7 Nem Eça nem Ramalho foram rigorosamente telúricos e, entretanto, sua vitalidade nas letras portuguesas é das que repelem, meio século depois de mortos os dois grandes críticos, 10 qualquer unguento ou óleo de complacência com que hoje se pretenda adoçar a revisão do seu valor social, os dois tendo atuado como revolucionários ou, antes, renovadores não só das 13 convenções estéticas da língua e da literatura, como das convenções sociais do povo e da nação que criticaram duramente para, afinal, terminarem cheios de ternura patriótica 16 e até mística pela tradição portuguesa. Um, revoltado contra o “francesismo”, ou', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q8 Item 3 (TPS 2014):  | Quanto a mim mesma, sem mentir nem ser verdadeira — como naquele momento em que ontem de manhã estava sentada à mesa do café — quanto a mim mesma, sempre', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q8 Item 4 (TPS 2014):  | conservei uma aspa à esquerda e outra à direita de mim. De algum modo “como se não fosse eu” era mais amplo do que se fosse — uma vida inexistente me possuía toda e me ocupava 7 como uma invenção. (...) Enquanto eu mesma era, mais do que limpa e correta, era uma réplica bonita. Pois tudo isso é o que provavelmente 10 me torna generosa e bonita. Basta o olhar de um homem experimentado para que ele avalie que eis uma mulher de generosidade e graça, e que não dá trabalho, e que não rói um 13 homem: mulher que sorri e ri. Essa imagem de mim entre aspas me satisfazia, e não apenas superficialmente. Eu era a imagem do que não era, e 16 essa imagem do não ser me cumulava toda: um dos modos mais fortes é ser negativamente. Como eu não sabia o que era, então “não ser” era a minha maior aproximação ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q9 Item 1 (TPS 2014): Em relação ao texto I acima, julgue (C ou E) os itens seguintes. 1 Em língua portuguesa, as expressões “estar entre aspas” e “viver entre parênteses” equivalem-se, pois ambas significam um estado de suspensão ou de espera diante de acontecimentos. 2 A autora do texto estabelece forte oposição entre “ser” e “não- ser”, optando pelo último, uma vez que “ser” poderia aproximá-la de uma forma aparente e mentirosa para a qual não se encontra preparada. 3 A sentença “Eu era a imagem do que não era” (R | Por mais que se escoem coisas para a lata do lixo, clipes, cãibras, suores,', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q9 Item 2 (TPS 2014): Em relação ao texto I acima, julgue (C ou E) os itens seguintes. 1 Em língua portuguesa, as expressões “estar entre aspas” e “viver entre parênteses” equivalem-se, pois ambas significam um estado de suspensão ou de espera diante de acontecimentos. 2 A autora do texto estabelece forte oposição entre “ser” e “não- ser”, optando pelo último, uma vez que “ser” poderia aproximá-la de uma forma aparente e mentirosa para a qual não se encontra preparada. 3 A sentença “Eu era a imagem do que não era” (R | restos do dia prolixo, por mais que a mesa imponha o frio irrevogável do aço, 7 combatendo o que em mim contenha a linha flexível de um abraço, sei que um murmúrio clandestino 10 circula entre o rio de meus ossos: janelas para um mar-abrigo de marasmos e destroços. 13 Na linha anônima do verso aposto no oposto de meu sim, apago o nome e a memória 16 num Antônio antônimo de mim. Antonio Carlos Secchin. Autoria. In: Todos os ventos. Rio de Janeiro: Nova Fronteira, 2002, p.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q10 Item 1 (TPS 2014): Em relação ao poema acima, julgue (C ou E) os itens subsequentes. | Em “aposto no oposto de meu sim” (v.14), a função da palavra “aposto”, tal como se lê no verso, é especificar ou explicar um elemento do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q10 Item 2 (TPS 2014): Em relação ao poema acima, julgue (C ou E) os itens subsequentes. | O autor estabelece uma oposição entre “linha flexível” (v.8) e “linha anônima” (v.13) para demonstrar que a autoria do poema é indeterminada ou questionável.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q10 Item 3 (TPS 2014): Em relação ao poema acima, julgue (C ou E) os itens subsequentes. | Para reforçar as noções do combate contra si mesmo e da consciência de “um murmúrio clandestino” (v.9), o autor evita a utilização de rimas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q10 Item 4 (TPS 2014): Em relação ao poema acima, julgue (C ou E) os itens subsequentes. | No verso “num Antônio antônimo de mim” (v.16), o poeta explora o fato de que tanto “Antônio” quanto “antônimo” compartilham a mesma raiz etimológica, que indica oposição, como em antissemita e antialérgico.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q11 Item 1 (TPS 2014): Em relação aos textos I e II, julgue (C ou E) os itens a seguir. | Tal como o eu lírico do poema (texto II), a narradora do texto I está envolvida com a autoria do texto literário, como evidencia o trecho “‘não ser’ era a minha maior aproximação da verdade” (R.18).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q11 Item 2 (TPS 2014): Em relação aos textos I e II, julgue (C ou E) os itens a seguir. | Há comparação entre o trecho “eu pelo menos tinha o ‘não’, tinha o meu oposto”, nas linhas 19 e 20 do texto I, e o verso 14 do texto II: “aposto no oposto de meu sim”; verifica-se que ambos os autores exploram aspectos e contingências de uma dimensão contrária ao ser ou a ele contraditória.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q11 Item 3 (TPS 2014): Em relação aos textos I e II, julgue (C ou E) os itens a seguir. | Existe semelhança temática entre o que afirma Clarice Lispector em “pelo menos eu tinha o lado avesso” (texto I/R.18- 19) e Antonio Carlos Secchin no verso “num Antônio antônimo de mim” (texto II/v.16): ambas as citações tratam da oposição ao eu.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q11 Item 4 (TPS 2014): Em relação aos textos I e II, julgue (C ou E) os itens a seguir. | Na comparação entre os textos I e II, percebe-se que o poeta descarta “clipes, cãibras, suores, / restos do dia prolixo” (v.3 e v.4), ao passo que a ficcionista conserva “uma aspa à esquerda e outra à direita” (R.4), o que demonstra que, com relação a bens materiais, os dois autores expressam atitudes diferentes.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q13 Item 1 (TPS 2014): No que se refere aos sentidos do texto de E. Araújo, julgue (C ou E) os itens subsequentes. | Infere-se da argumentação de Oriana Fallaci que, para a escritora, “um diálogo que determina um diálogo” (R.17-18) corresponde à forma de se concentrar cada fala em um bloco paragráfico, iniciado por travessão.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q13 Item 2 (TPS 2014): No que se refere aos sentidos do texto de E. Araújo, julgue (C ou E) os itens subsequentes. | No sexto parágrafo (R.38-54), o autor remete à ideia de licença poética, que está associada, no texto, ao despertar da consciência dos escritores quanto à forma de suas obras.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q13 Item 3 (TPS 2014): No que se refere aos sentidos do texto de E. Araújo, julgue (C ou E) os itens subsequentes. | Depreende-se das ideias desenvolvidas no trecho da citação de Roland Barthes que o sentido de “valor-gênio” (R.53) relaciona-se à obra cuja forma não exige muito trabalho e em cujo valor prevalece o talento do autor.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q13 Item 4 (TPS 2014): No que se refere aos sentidos do texto de E. Araújo, julgue (C ou E) os itens subsequentes. | Depreende-se do texto que a escritora Oriana Fallaci protestou contra a formatação de seu original traduzido porque almejava, com a obra Um homem, ficar conhecida por sua técnica inovadora na apresentação de diálogos, integrando estilo e forma.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q14 Item 1 (TPS 2014): Com relação aos aspectos morfossintáticos do texto, julgue (C ou E) os seguintes itens. | O trecho “A exclamação, patética, vinha da famosa jornalista internacional Oriana Fallaci (no caso, como escritora),” (R.3-4), em que se verifica um aposto especificativo, pode ser assim reescrito em estrutura de aposto explicativo: A exclamação, patética, vinha de Oriana Fallaci, a famosa jornalista internacional (no caso, como escritora).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q14 Item 2 (TPS 2014): Com relação aos aspectos morfossintáticos do texto, julgue (C ou E) os seguintes itens. | O emprego de “concebera” (R.8), no pretérito mais-que-perfeito do indicativo, justifica-se, no texto, como traço estilístico da linguagem culta formal, visto que, em normas estritamente gramaticais, não há respaldo para esse uso.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q14 Item 3 (TPS 2014): Com relação aos aspectos morfossintáticos do texto, julgue (C ou E) os seguintes itens. | Na linha 3, as vírgulas que isolam o termo “patética” foram empregadas para enfatizar o atributo de “exclamação”, mas a supressão dessa pontuação manteria a correção gramatical do trecho.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q14 Item 4 (TPS 2014): Com relação aos aspectos morfossintáticos do texto, julgue (C ou E) os seguintes itens. | Em “Meu Deus, o que fizeram do meu livro?” (R.1-2), a expressão “Meu Deus” tem função apelativa na estrutura oracional em que ocorre e, por estar subordinada a essa estrutura, não poderia ser seguida de ponto de exclamação em lugar da vírgula, ainda que se fizesse a alteração gráfica necessária no restante desse texto. ADMISSÃO À CARREIRA DE DIPLOMATA – MANHÃ – 6 – ||IRBR14DIPL_001_01N157490|| CESPE/UnB – IRBr DIPLOMATA – Aplicação: 2014 POLÍTICA INTERNACIONAL', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q15 Item 1 (TPS 2014): Acerca dos países da América do Sul e de suas políticas externas e suas relações com o Brasil, julgue (C ou E) os próximos itens. | Nos últimos anos, a Colômbia passou a priorizar, na área de política externa, a América do Sul como o espaço de sua atuação e atribuir maior relevância à sua relação com os países da região, manifestada tanto em sua adesão à UNASUL quanto na assinatura de acordos de complementação econômica, os quais, no caso do Brasil, deverão praticamente zerar as tarifas de importação dos produtos brasileiros até 2018.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q15 Item 2 (TPS 2014): Acerca dos países da América do Sul e de suas políticas externas e suas relações com o Brasil, julgue (C ou E) os próximos itens. | Ao longo da última década do século passado, a Argentina reforçou, no plano da política externa, sua relação preferencial com os EUA e aprofundou, na área econômica, o processo de integração com o Brasil, no âmbito do MERCOSUL, de modo que pôde enfrentar as turbulências do final da década e inaugurar o século XXI com estabilidade política interna e integração na América do Sul.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q15 Item 3 (TPS 2014): Acerca dos países da América do Sul e de suas políticas externas e suas relações com o Brasil, julgue (C ou E) os próximos itens. | Durante o período Chávez, a política externa venezuelana experimentou mudanças profundas nas identidades que condicionam sua formulação, em especial a afirmação de sua condição sul-americana e de valores terceiro-mundistas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q15 Item 4 (TPS 2014): Acerca dos países da América do Sul e de suas políticas externas e suas relações com o Brasil, julgue (C ou E) os próximos itens. | A percepção do Brasil como rival, que orientou a elaboração da política externa argentina ao longo de boa parte do século XX, foi gradualmente substituída pela ideia de um país amigo, em cujo governo as elites argentinas poderiam confiar em momentos críticos, como a Guerra das Malvinas e o processo de redemocratização, que favoreceu a cooperação bilateral nos campos da segurança e da defesa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q16 Item 1 (TPS 2014): No que se refere à política externa da China, da Índia e do Japão e às suas relações com o Brasil, julgue (C ou E) os itens seguintes. | Brasil e China organizam sua parceria estratégica no marco da Comissão Sino-Brasileira de Alto Nível de Concertação e Cooperação, em cuja reunião mais recente se decidiu dedicar especial atenção aos segmentos de maior valor agregado, ao agronegócio e aos projetos-chave de energia e infraestrutura.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q16 Item 2 (TPS 2014): No que se refere à política externa da China, da Índia e do Japão e às suas relações com o Brasil, julgue (C ou E) os itens seguintes. | Nos últimos anos, a política externa da Índia buscou substituir a identidade terceiro-mundista, que lhe impunha complexa agenda de negociações, por um perfil simplificado de polo geopolítico, ao impor-se aos EUA na questão nuclear e ao confrontar a China em disputas territoriais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q16 Item 4 (TPS 2014): No que se refere à política externa da China, da Índia e do Japão e às suas relações com o Brasil, julgue (C ou E) os itens seguintes. | A China busca, no plano de sua política externa, o crescimento e a estabilidade econômica, considerados necessários para garantir sua soberania e unidade territorial e sua afirmação como importante ator político global, o que explica a diversificação de suas iniciativas, quer no plano bilateral, mediante parcerias estratégicas, quer no multilateral, em foros como o BRICS e o BASIC.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q17 Item 1 (TPS 2014): Acerca de conceitos, atores, instituições e teorias das relações internacionais, julgue (C ou E) os itens subsecutivos. | Constituídas pelos Estados nacionais, as organizações internacionais governamentais são agentes desses atores principais e realizam apenas a vontade da maioria de seus integrantes, de forma objetiva e direta.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q17 Item 2 (TPS 2014): Acerca de conceitos, atores, instituições e teorias das relações internacionais, julgue (C ou E) os itens subsecutivos. | As premissas compartilhadas pelos realistas, em todas as suas vertentes, incluem a possibilidade de distinção das políticas externa e interna desenvolvidas pelos Estados nacionais, a predominância da preocupação com a própria segurança e a valorização do poder como o principal elemento explicativo do comportamento dos Estados no ambiente internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q17 Item 3 (TPS 2014): Acerca de conceitos, atores, instituições e teorias das relações internacionais, julgue (C ou E) os itens subsecutivos. | Criada no contexto da política externa norte-americana da década de 70 do século passado, reconhecidamente realista, a alta política, marcada pelo emprego da força militar, distingue- se da baixa política, caracterizada pela diplomacia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q17 Item 4 (TPS 2014): Acerca de conceitos, atores, instituições e teorias das relações internacionais, julgue (C ou E) os itens subsecutivos. | A noção de polos de poder permanece útil aos analistas das relações internacionais contemporâneas, mesmo quando se quer aludir a um sistema em permanente transformação, cuja dinâmica implica redefinir, repetidamente, suas polaridades.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q18 Item 1 (TPS 2014): Acerca dos recentes desenvolvimentos no Oriente Médio, no Irã e no Iraque e das suas implicações para a política externa brasileira, julgue (C ou E) os itens seguintes. | A questão síria é mais simples que as questões iranianas e iraquianas, por se definir em termos geopolíticos clássicos, e requer solução que envolva decisivamente os EUA, a Rússia e a China, dadas as relativamente superficiais implicações para o Oriente Médio em termos étnicos, religiosos ou políticos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q18 Item 2 (TPS 2014): Acerca dos recentes desenvolvimentos no Oriente Médio, no Irã e no Iraque e das suas implicações para a política externa brasileira, julgue (C ou E) os itens seguintes. | A Declaração de Teerã e o Plano de Ação Conjunto de Genebra são semelhantes no que diz respeito ao tratamento da questão nuclear iraniana, por proporem essencialmente os mesmos passos para a sua solução, mas se diferenciam pelos contextos políticos distintos em que surgiram e por seus artífices, o que explica o fracasso da primeira e o êxito do segundo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q18 Item 3 (TPS 2014): Acerca dos recentes desenvolvimentos no Oriente Médio, no Irã e no Iraque e das suas implicações para a política externa brasileira, julgue (C ou E) os itens seguintes. | O Brasil defende como solução para a questão palestina o reconhecimento de dois Estados, consideradas as fronteiras de 1967, por ser a única capaz de atender aos anseios dos povos da região e de promover a paz duradoura no Oriente Médio.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q18 Item 4 (TPS 2014): Acerca dos recentes desenvolvimentos no Oriente Médio, no Irã e no Iraque e das suas implicações para a política externa brasileira, julgue (C ou E) os itens seguintes. | Iniciada com a virada do século, a Primavera Árabe, caracterizada pela série de manifestações que mudou governos nos países árabes, especialmente no norte da África, promoveu a consolidação de regimes democráticos na região e influenciou positivamente as negociações entre Israel e Palestina. ADMISSÃO À CARREIRA DE DIPLOMATA – MANHÃ – 7 – ||IRBR14DIPL_001_01N157490|| CESPE/UnB – IRBr DIPLOMATA – Aplicação: 2014', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q19 Item 1 (TPS 2014): Com relação à evolução da política externa brasileira desde 1945 e suas principais linhas de ação, julgue (C ou E) os próximos itens. | Em 2005, no marco das discussões sobre a reforma do Conselho de Segurança da ONU, o G-4, com o apoio de vários outros Estados, submeteu à Assembleia Geral da organização internacional proposta de alteração da composição do Conselho para inserir seis novos membros permanentes e quatro não permanentes, sem uso do veto, até a realização de conferência de revisão da reforma, quinze anos depois.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q19 Item 2 (TPS 2014): Com relação à evolução da política externa brasileira desde 1945 e suas principais linhas de ação, julgue (C ou E) os próximos itens. | Em articulação com outros países em desenvolvimento, o Brasil favorece um tipo de multilateralismo econômico em que, devido à sua presença majoritária, os países em desenvolvimento, pela maioria dos votos, logram obter seus objetivos comuns, como foi o caso dos contenciosos da gasolina contra a UE e do algodão contra o NAFTA, no âmbito da OMC.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q19 Item 3 (TPS 2014): Com relação à evolução da política externa brasileira desde 1945 e suas principais linhas de ação, julgue (C ou E) os próximos itens. | A associação dos objetivos da política externa brasileira à promoção do desenvolvimento econômico e da inclusão social, marcada pelo histórico discurso de Araújo Castro na abertura da Assembleia Geral da ONU, há meio século, passou a incluir, nas últimas décadas, também a questão ambiental, como ilustram a Rio 92 e a Rio+20.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q19 Item 4 (TPS 2014): Com relação à evolução da política externa brasileira desde 1945 e suas principais linhas de ação, julgue (C ou E) os próximos itens. | O Brasil defende a reforma das instituições de governança global, que devem se tornar mais representativas dos Estados que as constituem, e a redistribuição de poder observada nas relações internacionais desde o fim da Segunda Guerra Mundial.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q20 Item 1 (TPS 2014): No que concerne às relações entre a África e o Brasil, julgue (C ou E) os seguintes itens. | Nos últimos anos, o comércio exterior entre o Brasil e a África cresceu exponencialmente, transformou o continente em um dos principais parceiros comerciais brasileiros, em razão do tamanho do mercado de cerca de 1,5 bilhão de habitantes, do ritmo de seu crescimento econômico e da natureza do intercâmbio, e gerou superávit para o Brasil, que exporta, sobretudo, produtos com alto valor agregado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q20 Item 2 (TPS 2014): No que concerne às relações entre a África e o Brasil, julgue (C ou E) os seguintes itens. | Na esteira da criação do IBAS, o Brasil e a África do Sul sugeriram a criação da Cúpula América do Sul-África, ainda em 2003, em cujo marco os chefes de Estado e de governo dos países membros se reúnem anualmente para tratar do controle de fluxos migratórios internos, do combate conjunto à pirataria e do aperfeiçoamento da governança das instituições políticas e financeiras internacionais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q20 Item 3 (TPS 2014): No que concerne às relações entre a África e o Brasil, julgue (C ou E) os seguintes itens. | As iniciativas de política externa que condicionaram a ampliação da importância da África para o Brasil incluem a criação da Comunidade dos Países de Língua Portuguesa, no governo de Fernando Henrique Cardoso.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Política Internacional', NULL, 'Q20 Item 4 (TPS 2014): No que concerne às relações entre a África e o Brasil, julgue (C ou E) os seguintes itens. | Desde 2005, o Brasil e a União Africana estabeleceram formalmente um diálogo institucional, em que se privilegiam as áreas de política social e de cooperação sul-sul, além de parcerias destinadas a promover o desenvolvimento agrícola e a segurança alimentar.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q21 Item 1 (TPS 2014): No que se refere à Rússia e às suas relações com os países europeus e com os EUA desde o final da Guerra Fria, julgue (C ou E) os itens a seguir. | A expansão da OTAN tornou-se um novo ingrediente para fricções entre os russos e os membros da Aliança Atlântica. Com essa expansão, passaram a fazer parte da OTAN alguns países participantes do antigo Pacto de Varsóvia, além de vários países balcânicos e bálticos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q21 Item 2 (TPS 2014): No que se refere à Rússia e às suas relações com os países europeus e com os EUA desde o final da Guerra Fria, julgue (C ou E) os itens a seguir. | Ao longo da última década, a Rússia tem enfrentado períodos de grande tensão com várias repúblicas que faziam parte da União Soviética, como é o caso da atual crise na Ucrânia, em que o governo russo percebe a busca de autonomia como ação incentivada por países ocidentais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q21 Item 3 (TPS 2014): No que se refere à Rússia e às suas relações com os países europeus e com os EUA desde o final da Guerra Fria, julgue (C ou E) os itens a seguir. | Os riscos, reais ou imaginários, percebidos pela Europa em relação à Rússia não se limitam a problemas tradicionais de segurança, como manutenção e proliferação de armas convencionais e nucleares. O risco percebido envolve, entre outras questões, a segurança energética da Europa, visto que vários países europeus são dependentes do fornecimento de gás pela Rússia, o que não ocorre, por exemplo, com a Alemanha, que conta com muitas usinas atômicas e goza de autonomia energética.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q21 Item 4 (TPS 2014): No que se refere à Rússia e às suas relações com os países europeus e com os EUA desde o final da Guerra Fria, julgue (C ou E) os itens a seguir. | Na Rússia, a ascensão política de Vladimir Putin representou, em grande medida, o reforço da autoestima e orgulho nacionais. Para garantir o sucesso de sua política econômica, Putin tem defendido uma forte aproximação dos países ocidentais, notadamente de seus vizinhos europeus, calcada no estreitamento de relações comerciais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q22 Item 1 (TPS 2014): O Brasil tem um extenso litoral, que lhe assegura posição política e estratégica privilegiada. O mar sempre foi elemento importante na história do país e tudo indica que, no futuro, ainda será mais relevante. A propósito desse tema, julgue (C ou E) os itens subsecutivos. | Em meio a polêmicas a respeito da largura máxima do mar territorial e da delimitação de outros espaços marítimos, o Brasil, no começo da última década de 70, como forma de proteger seus interesses econômicos e de segurança, estendeu seu mar territorial para duzentas milhas marítimas, o que afetou suas relações com todos os países latino-americanos que julgaram ilegítima tal medida.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q22 Item 2 (TPS 2014): O Brasil tem um extenso litoral, que lhe assegura posição política e estratégica privilegiada. O mar sempre foi elemento importante na história do país e tudo indica que, no futuro, ainda será mais relevante. A propósito desse tema, julgue (C ou E) os itens subsecutivos. | Os primeiros indícios de petróleo na camada de pré-sal foram encontrados na Bacia de Santos e a atual expectativa do governo brasileiro é explorar grandes quantidades de petróleo encobertos por camadas de sal abaixo do leito do mar brasileiro.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q22 Item 3 (TPS 2014): O Brasil tem um extenso litoral, que lhe assegura posição política e estratégica privilegiada. O mar sempre foi elemento importante na história do país e tudo indica que, no futuro, ainda será mais relevante. A propósito desse tema, julgue (C ou E) os itens subsecutivos. | Como parte dos esforços empreendidos para estender o limite exterior da plataforma continental do Brasil, os trabalhos realizados no âmbito do Plano de Levantamento da Plataforma Continental Brasileira (LEPLAC) aumentam as oportunidades de descoberta de recursos naturais, como gás e petróleo, na plataforma continental, independentemente de seus futuros limites.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q22 Item 4 (TPS 2014): O Brasil tem um extenso litoral, que lhe assegura posição política e estratégica privilegiada. O mar sempre foi elemento importante na história do país e tudo indica que, no futuro, ainda será mais relevante. A propósito desse tema, julgue (C ou E) os itens subsecutivos. | O Brasil possui um mar territorial de doze milhas marítimas e uma zona econômica exclusiva (ZEE) de 200 milhas marítimas. Na ZEE, o Brasil exerce direitos de soberania que lhe permitem explorar economicamente e gerir recursos naturais nesse amplo espaço marítimo. ADMISSÃO À CARREIRA DE DIPLOMATA – MANHÃ – 8 – ||IRBR14DIPL_001_01N157490|| CESPE/UnB – IRBr DIPLOMATA – Aplicação: 2014', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q23 Item 1 (TPS 2014): A preocupação com os direitos humanos é antiga, mas sua positivação internacional é fenômeno recente, iniciado no pós- Segunda Guerra Mundial. Acerca desse assunto, julgue (C ou E) os itens subsecutivos. | Assinada em 1948, no âmbito da Assembleia Geral das Nações Unidas, a Declaração Universal dos Direitos Humanos, ainda que não obrigue legalmente os Estados a cumprir suas disposições, não só influenciou muitas constituições nacionais, que expressam, em seu texto, o propósito de garantir a promoção e a proteção dos direitos humanos, mas também impulsionou a criação de convenções internacionais que visam proteger os direitos humanos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q23 Item 2 (TPS 2014): A preocupação com os direitos humanos é antiga, mas sua positivação internacional é fenômeno recente, iniciado no pós- Segunda Guerra Mundial. Acerca desse assunto, julgue (C ou E) os itens subsecutivos. | É obrigação do Alto Comissariado das Nações Unidas para Refugiados (ACNUR) enviar anualmente ao Conselho de Segurança das Nações Unidas uma lista vermelha, composta pelos países considerados responsáveis pela busca do refúgio de seus nacionais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q23 Item 3 (TPS 2014): A preocupação com os direitos humanos é antiga, mas sua positivação internacional é fenômeno recente, iniciado no pós- Segunda Guerra Mundial. Acerca desse assunto, julgue (C ou E) os itens subsecutivos. | No continente americano, o Sistema Interamericano de Direitos Humanos é composto por dois órgãos permanentes, com sede em Washington: a Comissão Interamericana, que examina reclamações de indivíduos contra supostas violações aos direitos humanos, e a Corte Interamericana de Direitos Humanos, que julga determinados casos de violações.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q23 Item 4 (TPS 2014): A preocupação com os direitos humanos é antiga, mas sua positivação internacional é fenômeno recente, iniciado no pós- Segunda Guerra Mundial. Acerca desse assunto, julgue (C ou E) os itens subsecutivos. | Criado em 2006, o Conselho de Direitos Humanos sucedeu a Comissão das Nações Unidas para os Direitos Humanos e, no atual Conselho, diferentemente do que ocorria na Comissão, não são secretas as votações para eleger seus membros.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q24 Item 1 (TPS 2014): Várias iniciativas de integração passaram a compor a agenda dos países sul-americanos nas últimas décadas. MERCOSUL, ALCSA, IIRSA, CASA e UNASUL são siglas que se tornaram correntes no noticiário da região. Acerca desse assunto, julgue (C ou E) os próximos itens. | Do ponto de vista político, a Cláusula Democrática é a que mais se destaca no Protocolo Ouro Preto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q24 Item 2 (TPS 2014): Várias iniciativas de integração passaram a compor a agenda dos países sul-americanos nas últimas décadas. MERCOSUL, ALCSA, IIRSA, CASA e UNASUL são siglas que se tornaram correntes no noticiário da região. Acerca desse assunto, julgue (C ou E) os próximos itens. | Estabelecida em 2000, a Iniciativa para a Integração da Infraestrutura Regional Sul-Americana (IIRSA), que é considerada por alguns o primeiro grande esforço prático para a superação das deficiências no plano da infraestrutura, foi incorporada, posteriormente, ao Conselho Sul-Americano de Infraestrutura e Planejamento da UNASUL.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q24 Item 3 (TPS 2014): Várias iniciativas de integração passaram a compor a agenda dos países sul-americanos nas últimas décadas. MERCOSUL, ALCSA, IIRSA, CASA e UNASUL são siglas que se tornaram correntes no noticiário da região. Acerca desse assunto, julgue (C ou E) os próximos itens. | A CASA tornou-se UNASUL em 2007 e, em 2008, foi criado o CDS, cujo objetivo é contribuir para a unidade sul-americana na área de segurança, complementando, assim, as várias vertentes da UNASUL, que já havia avançado em temas como livre-comércio, integração comercial, infraestrutura e energia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q24 Item 4 (TPS 2014): Várias iniciativas de integração passaram a compor a agenda dos países sul-americanos nas últimas décadas. MERCOSUL, ALCSA, IIRSA, CASA e UNASUL são siglas que se tornaram correntes no noticiário da região. Acerca desse assunto, julgue (C ou E) os próximos itens. | No MERCOSUL, como nas demais iniciativas de integração na América do Sul, predomina a dimensão intergovernamental sobre a supranacional. O Protocolo de Ouro Preto, de 1994, atribuiu ao MERCOSUL personalidade jurídica como ator internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q25 Item 1 (TPS 2014): É possível afirmar que Barak Obama representa os EUA em sua dimensão multicultural, multirracial e globalizada. Na política externa, o governo Obama apresentou algumas novidades. A respeito desse assunto, julgue (C ou E) os itens seguintes. | Os EUA condenaram peremptoriamente as ações russas na Crimeia iniciadas em 2014 e, em seguida, suspenderam as negociações do acordo de comércio e investimento e, no plano militar, ameaçaram, nas Nações Unidas, utilizar armas convencionais para defender a autonomia dos ucranianos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q25 Item 2 (TPS 2014): É possível afirmar que Barak Obama representa os EUA em sua dimensão multicultural, multirracial e globalizada. Na política externa, o governo Obama apresentou algumas novidades. A respeito desse assunto, julgue (C ou E) os itens seguintes. | No primeiro ano de seu primeiro mandato, 2009-2012, Obama, no Cairo, fez um discurso que seria entendido como a expressão de sua intenção de estabelecer novo começo nas relações entre o mundo islâmico e os EUA.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q25 Item 3 (TPS 2014): É possível afirmar que Barak Obama representa os EUA em sua dimensão multicultural, multirracial e globalizada. Na política externa, o governo Obama apresentou algumas novidades. A respeito desse assunto, julgue (C ou E) os itens seguintes. | Em seu primeiro mandato presidencial, Obama buscou concluir com o presidente da Rússia o Novo Tratado de Redução de Armas Estratégicas (novo START), tentativa, contudo, malograda.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q25 Item 4 (TPS 2014): É possível afirmar que Barak Obama representa os EUA em sua dimensão multicultural, multirracial e globalizada. Na política externa, o governo Obama apresentou algumas novidades. A respeito desse assunto, julgue (C ou E) os itens seguintes. | A Índia, que não é signatária do Tratado de Não-Proliferação Nuclear (TNP), e os EUA assinaram um acordo em que foi reconhecido o status da Índia de Estado detentor de armas nucleares.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q26 Item 1 (TPS 2014): A Declaração do Milênio das Nações Unidas apoia os princípios consagrados na Agenda 21 e reafirma o compromisso de seus signatários com a implementação de diversos acordos ambientais. Com relação a esse tema, julgue (C ou E) os itens a seguir. | A Convenção das Nações Unidas sobre Mudança do Clima, cujo órgão supremo é a Conferência das Partes, foi designada Convenção-Quadro porque serve de base para a assinatura de outras convenções internacionais que versem sobre mudança climática.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q26 Item 2 (TPS 2014): A Declaração do Milênio das Nações Unidas apoia os princípios consagrados na Agenda 21 e reafirma o compromisso de seus signatários com a implementação de diversos acordos ambientais. Com relação a esse tema, julgue (C ou E) os itens a seguir. | Estabelecida durante a Rio-92, a Convenção sobre Diversidade Biológica funciona como espécie de arcabouço legal e político para acordos ambientais mais específicos, a exemplo do Protocolo de Cartagena sobre Biossegurança e a Convenção sobre Armamentos Químicos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q26 Item 3 (TPS 2014): A Declaração do Milênio das Nações Unidas apoia os princípios consagrados na Agenda 21 e reafirma o compromisso de seus signatários com a implementação de diversos acordos ambientais. Com relação a esse tema, julgue (C ou E) os itens a seguir. | Signatário, junto com quase 200 países, da chamada Convenção das Nações Unidas de Combate à Desertificação e Mitigação dos Efeitos das Secas, o Brasil, atuando em iniciativas bilaterais e multilaterais, é considerado uma das grandes lideranças globais na implementação dessa Convenção.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Língua Portuguesa', NULL, 'Q26 Item 4 (TPS 2014): A Declaração do Milênio das Nações Unidas apoia os princípios consagrados na Agenda 21 e reafirma o compromisso de seus signatários com a implementação de diversos acordos ambientais. Com relação a esse tema, julgue (C ou E) os itens a seguir. | Passo importante na evolução das discussões sobre meio ambiente, a Conferência de Estocolmo, de 1972, realizada no âmbito das Nações Unidas, mostrou que havia, naquele momento, grande convergência entre os países desenvolvidos e os países em desenvolvimento sobre a necessidade de reduzir, por um tempo, o ritmo de suas atividades industriais. ADMISSÃO À CARREIRA DE DIPLOMATA – MANHÃ – 9 – ||IRBR14DIPL_001_01N157490|| CESPE/UnB – IRBr DIPLOMATA – Aplicação: 2014 GEOGRAFIA', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q27 Item 1 (TPS 2014): Se necessário for definir um paradigma para a geopolítica desde que se constituiu como disciplina, certamente este seria o do realismo, no campo das relações internacionais. A obra de Friedrich Ratzel, teorizando geograficamente o Estado (1897), constitui uma fonte crucial para a análise das relações entre o Estado e o poder. B. Becker. A geopolítica na virada do milênio. In: Geografia: conceitos e temas, Castro et al. (Orgs.). Rio de Janeiro: Bertrand Brasil, 1995, p. 273 e 277 (com adaptações) | As leis do crescimento espacial dos Estados enunciadas por Ratzel retificam os princípios básicos do realismo político.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q27 Item 3 (TPS 2014): Se necessário for definir um paradigma para a geopolítica desde que se constituiu como disciplina, certamente este seria o do realismo, no campo das relações internacionais. A obra de Friedrich Ratzel, teorizando geograficamente o Estado (1897), constitui uma fonte crucial para a análise das relações entre o Estado e o poder. B. Becker. A geopolítica na virada do milênio. In: Geografia: conceitos e temas, Castro et al. (Orgs.). Rio de Janeiro: Bertrand Brasil, 1995, p. 273 e 277 (com adaptações) | Por reconhecer a exclusividade dos Estados como atores internacionais, o realismo político coaduna-se com os parâmetros da geopolítica clássica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q27 Item 4 (TPS 2014): Se necessário for definir um paradigma para a geopolítica desde que se constituiu como disciplina, certamente este seria o do realismo, no campo das relações internacionais. A obra de Friedrich Ratzel, teorizando geograficamente o Estado (1897), constitui uma fonte crucial para a análise das relações entre o Estado e o poder. B. Becker. A geopolítica na virada do milênio. In: Geografia: conceitos e temas, Castro et al. (Orgs.). Rio de Janeiro: Bertrand Brasil, 1995, p. 273 e 277 (com adaptações) | Por considerar o Estado como organismo vivo, a geografia política ratzeliana contradiz o paradigma do realismo político.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q28 Item 1 (TPS 2014): Karl Haushofer era militar de carreira, mas sua saúde frágil tornou-lhe difícil o exercício de comando na guerra. Ele se orientou, então, para as funções do Estado-Maior. E serve, por isso, de 1908 a 1910, como adido militar em Tóquio. Ele é, assim, iniciado à geopolítica dos militares e à dos diplomatas. P. Claval. Géopolitique et géoestratégie. Paris: Nathan, 1994, p. 25 (com adaptações). Em relação à hipótese geoestratégica do poder mundial elaborada por Karl Haushofer, julgue (C ou E) os ite | A panregião da Euráfrica, sob liderança alemã, englobava a Rússia, subordinada aos imperativos geopolíticos das potências europeias.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q28 Item 2 (TPS 2014): Karl Haushofer era militar de carreira, mas sua saúde frágil tornou-lhe difícil o exercício de comando na guerra. Ele se orientou, então, para as funções do Estado-Maior. E serve, por isso, de 1908 a 1910, como adido militar em Tóquio. Ele é, assim, iniciado à geopolítica dos militares e à dos diplomatas. P. Claval. Géopolitique et géoestratégie. Paris: Nathan, 1994, p. 25 (com adaptações). Em relação à hipótese geoestratégica do poder mundial elaborada por Karl Haushofer, julgue (C ou E) os ite | A idealização de panregiões comandadas por potências específicas da Europa, Ásia e América estava associada à neutralização do Império britânico, concebido como panregião fragmentada.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q28 Item 3 (TPS 2014): Karl Haushofer era militar de carreira, mas sua saúde frágil tornou-lhe difícil o exercício de comando na guerra. Ele se orientou, então, para as funções do Estado-Maior. E serve, por isso, de 1908 a 1910, como adido militar em Tóquio. Ele é, assim, iniciado à geopolítica dos militares e à dos diplomatas. P. Claval. Géopolitique et géoestratégie. Paris: Nathan, 1994, p. 25 (com adaptações). Em relação à hipótese geoestratégica do poder mundial elaborada por Karl Haushofer, julgue (C ou E) os ite | A formação das panregiões impedia a consolidação de espaços autárquicos, devido às diversas faixas latitudinais dessas áreas de influência estratégicas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q28 Item 4 (TPS 2014): Karl Haushofer era militar de carreira, mas sua saúde frágil tornou-lhe difícil o exercício de comando na guerra. Ele se orientou, então, para as funções do Estado-Maior. E serve, por isso, de 1908 a 1910, como adido militar em Tóquio. Ele é, assim, iniciado à geopolítica dos militares e à dos diplomatas. P. Claval. Géopolitique et géoestratégie. Paris: Nathan, 1994, p. 25 (com adaptações). Em relação à hipótese geoestratégica do poder mundial elaborada por Karl Haushofer, julgue (C ou E) os ite | Segundo essa hipótese, o objetivo estratégico baseava-se na consolidação do poder marítimo e naval mundial sob o comando da Alemanha.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q29 Item 1 (TPS 2014): A aparição das chamadas cidades mundiais e das cidades globais se explica pela necessidade de organização e controle da economia global. O termo cidade global, em sua versão mais topológica, é definido por Saskia Sassen como um território onde se exerce uma série de funções de organização e controle na economia global e nos fluxos de investimentos em escala planetária. O. Nel.Lo e F. Muñoz. El proceso de urbanización. In.: Geografía humana, J. Romero et al (Coord.). Barcelona: Ariel, 2008, p. 32 | A dinâmica fundamental do novo processo de urbanização pressupõe que, quanto mais a economia for globalizada, maior será a convergência de funções centrais nas cidades globais, cuja densidade demográfica elevada expressa espacialmente essa dinâmica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q29 Item 2 (TPS 2014): A aparição das chamadas cidades mundiais e das cidades globais se explica pela necessidade de organização e controle da economia global. O termo cidade global, em sua versão mais topológica, é definido por Saskia Sassen como um território onde se exerce uma série de funções de organização e controle na economia global e nos fluxos de investimentos em escala planetária. O. Nel.Lo e F. Muñoz. El proceso de urbanización. In.: Geografía humana, J. Romero et al (Coord.). Barcelona: Ariel, 2008, p. 32 | A dispersão territorial das atividades econômicas contribui, por meio, por exemplo, de tecnologias da informação, para o crescimento das funções e das operações centralizadas nas cidades globais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q29 Item 3 (TPS 2014): A aparição das chamadas cidades mundiais e das cidades globais se explica pela necessidade de organização e controle da economia global. O termo cidade global, em sua versão mais topológica, é definido por Saskia Sassen como um território onde se exerce uma série de funções de organização e controle na economia global e nos fluxos de investimentos em escala planetária. O. Nel.Lo e F. Muñoz. El proceso de urbanización. In.: Geografía humana, J. Romero et al (Coord.). Barcelona: Ariel, 2008, p. 32 | A globalização econômica contribui para uma nova geografia da centralidade e da marginalidade, tornando as cidades globais lugares de concentração de poder econômico, ao passo que cidades que foram centros manufatureiros experimentam nítido declínio.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q29 Item 4 (TPS 2014): A aparição das chamadas cidades mundiais e das cidades globais se explica pela necessidade de organização e controle da economia global. O termo cidade global, em sua versão mais topológica, é definido por Saskia Sassen como um território onde se exerce uma série de funções de organização e controle na economia global e nos fluxos de investimentos em escala planetária. O. Nel.Lo e F. Muñoz. El proceso de urbanización. In.: Geografía humana, J. Romero et al (Coord.). Barcelona: Ariel, 2008, p. 32 | O nível máximo de controle e de gerenciamento da indústria permanece concentrado em poucos centros financeiros diretores, como observado especialmente em cidades globais como Paris, São Paulo e Los Angeles, na década de 80 do século XX. ADMISSÃO À CARREIRA DE DIPLOMATA – MANHÃ – 10 – ||IRBR14DIPL_001_01N157490|| CESPE/UnB – IRBr DIPLOMATA – Aplicação: 2014', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q30 Item 1 (TPS 2014): Turistas, funcionários e gestores de empresas circulam pelo mundo, mas a maior parte dos que se deslocam por um tempo mais longo é constituída de migrantes internacionais. A pobreza é a principal causa da mobilidade, mas as defasagens entre sociedades jovens e em processo de envelhecimento, os conflitos, a difusão da informação, a redução dos custos de transporte e as demandas de mão de obra nos países do Norte alimentam os desejos de partida. M-F Durand et al. Atlas da mundialização. Compreende | Os fluxos migratórios sul-norte envolvem menos da metade dos migrantes internacionais; a maioria dos fluxos, menos conhecidos e menos midiatizados, é de orientação sul-sul.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q30 Item 2 (TPS 2014): Turistas, funcionários e gestores de empresas circulam pelo mundo, mas a maior parte dos que se deslocam por um tempo mais longo é constituída de migrantes internacionais. A pobreza é a principal causa da mobilidade, mas as defasagens entre sociedades jovens e em processo de envelhecimento, os conflitos, a difusão da informação, a redução dos custos de transporte e as demandas de mão de obra nos países do Norte alimentam os desejos de partida. M-F Durand et al. Atlas da mundialização. Compreende | As migrações são cada vez mais circulares; a Espanha, por exemplo, é um país de emigração, sobretudo de migrações empresariais, um país de trânsito para os africanos que vão para a França e um país de imigração do Marrocos e da Romênia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q30 Item 3 (TPS 2014): Turistas, funcionários e gestores de empresas circulam pelo mundo, mas a maior parte dos que se deslocam por um tempo mais longo é constituída de migrantes internacionais. A pobreza é a principal causa da mobilidade, mas as defasagens entre sociedades jovens e em processo de envelhecimento, os conflitos, a difusão da informação, a redução dos custos de transporte e as demandas de mão de obra nos países do Norte alimentam os desejos de partida. M-F Durand et al. Atlas da mundialização. Compreende | Ainda que estejam mundializadas, as migrações se regionalizaram; as regiões migratórias não abarcam continentes, mas correspondem a sistemas regionais em que há complementaridade entre a demanda e a oferta de trabalho e de população.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q30 Item 4 (TPS 2014): Turistas, funcionários e gestores de empresas circulam pelo mundo, mas a maior parte dos que se deslocam por um tempo mais longo é constituída de migrantes internacionais. A pobreza é a principal causa da mobilidade, mas as defasagens entre sociedades jovens e em processo de envelhecimento, os conflitos, a difusão da informação, a redução dos custos de transporte e as demandas de mão de obra nos países do Norte alimentam os desejos de partida. M-F Durand et al. Atlas da mundialização. Compreende | Um aspecto significativo das migrações atuais é o predomínio numérico de europeus, nos fluxos internacionais, em substituição ao predomínio de africanos, asiáticos e latino- americanos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q31 Item 1 (TPS 2014): Integração econômica regional é filha da globalização, é um fato da realidade mundial do momento. É um acontecimento que se reflete nas relações internacionais dos países. Muitas decisões hoje são tomadas de forma conjunta nos fóruns internacionais pelos países que pertencem a uma integração econômica regional. A geografia está ditando esse caminho. A. Menezes e P. Penna Filho. Integração regional. Os blocos econômicos nas relações internacionais. Rio de Janeiro: Campus, 2006, p. x. Acerca da fo | CADERNO DE PROVA OBJETIVA (1.ª FASE) SEGUNDA ETAPA LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Ao receber este caderno de prova, confira inicialmente se os seus dados pessoais, transcritos acima, estão corretos e coincidem com o que está registrado na sua folha de respostas. Confira também o seu nome em cada página numerada deste caderno. Em seguida, verifique se ele contém quarenta e duas questões, correspondentes à segunda etapa da prova objetiva, corretamente ordenadas de', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q31 Item 2 (TPS 2014): Integração econômica regional é filha da globalização, é um fato da realidade mundial do momento. É um acontecimento que se reflete nas relações internacionais dos países. Muitas decisões hoje são tomadas de forma conjunta nos fóruns internacionais pelos países que pertencem a uma integração econômica regional. A geografia está ditando esse caminho. A. Menezes e P. Penna Filho. Integração regional. Os blocos econômicos nas relações internacionais. Rio de Janeiro: Campus, 2006, p. x. Acerca da fo | The Beijing-Islamabad axis plays a central role in Asia’s geopolitics, from India’s rise to the prospects for a post-American Afghanistan, from the threat of nuclear', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2014, 'Geografia', NULL, 'Q31 Item 3 (TPS 2014): Integração econômica regional é filha da globalização, é um fato da realidade mundial do momento. É um acontecimento que se reflete nas relações internacionais dos países. Muitas decisões hoje são tomadas de forma conjunta nos fóruns internacionais pelos países que pertencem a uma integração econômica regional. A geografia está ditando esse caminho. A. Menezes e P. Penna Filho. Integração regional. Os blocos econômicos nas relações internacionais. Rio de Janeiro: Campus, 2006, p. x. Acerca da fo | terrorism to the continent’s new map of mines, ports and pipelines. China is Pakistan’s great economic hope and its most trusted military partner; Pakistan is the battleground for 7 China’s encounters with Islamic militancy and the heart of its efforts to counter-balance the emerging US-India partnership. For decades, each country has been the other’s only 10 ‘all-weather’ friend. Yet the relationship is still little understood. The wildest claims about it are widely be', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
